previewCss:
.darma-loader-darma-b15-curling-stone { --accent: var(--loader-color, #b91c1c); --accent-2: var(--loader-secondary-color, #60a5fa); width: var(--loader-size, 130px); height: calc(var(--loader-size, 130px) * .62); position: relative; }
.darma-loader-darma-b15-curling-stone .darma-loader-darma-b15-curling-stone__house { position: absolute; right: 5%; top: 8%; width: 42%; height: 84%; border-radius: 50%; background: radial-gradient(circle, var(--accent) 0 17%, transparent 17% 33%, var(--accent-2) 33% 50%, transparent 50% 68%, color-mix(in srgb, var(--accent) 45%, transparent) 68% 84%, transparent 84%); }
.darma-loader-darma-b15-curling-stone .darma-loader-darma-b15-curling-stone__stone { position: absolute; left: 2%; top: 34%; width: 20%; height: 32%; border-radius: 50%; background: radial-gradient(circle at 38% 32%, #94a3b8, #334155); animation: darma-loader-darma-b15-curling-stone-curl-slide calc(var(--loader-speed, 1s) * 2.8) cubic-bezier(.15, .65, .3, 1) infinite; }
.darma-loader-darma-b15-curling-stone .darma-loader-darma-b15-curling-stone__stone::after { content: ''; position: absolute; left: 30%; bottom: 92%; width: 40%; height: 34%; border-radius: 4px 4px 0 0; background: var(--accent-2); }
@keyframes darma-loader-darma-b15-curling-stone-curl-slide { 0% { opacity: 0; transform: translateX(0) rotate(0deg); } 8% { opacity: 1; } 76%, 90% { opacity: 1; transform: translateX(280%) rotate(210deg); } 100% { opacity: 0; transform: translateX(280%) rotate(210deg); } }

